const TIME_LIMIT: int = 1400;
const TH18_BALL: int = 416;

// GirlD03_at: VELTIME 90, target speed by difficulty, direction = bullet angle.
xformdef RAMP(target: fx, direction: angle) {
    set_gravity(((target - 1fx) / 90fx) * cos(direction), ((target - 1fx) / 90fx) * sin(direction));
    @90 add_speed(0fx);
    set_gravity(0fx, 0fx);
}

async sub shots() {
    wait(60);
    var rank: int = global(GVAR_RANK);
    var count: int = 5;
    var target: fx = 2.3fx;
    if rank == 1 { count = 10; target = 3.6fx; }
    if rank == 2 { count = 15; target = 4fx; }
    if rank == 3 { count = 17; target = 4fx; }
    for volley in 0..40 {
        var phase: angle = rand(65536) as angle;
        for i in 0..count {
            var shot_angle: angle = phase + ((i * 65536 / count) as angle);
            // Original birth animation displacement: -4 times initial velocity.
            _ = fire(TH18_BALL, 2, $self_x - 4fx * cos(shot_angle), $self_y - 4fx * sin(shot_angle), 1fx, shot_angle, RAMP(target, shot_angle), none);
        }
        wait(17);
    }
}

async sub girl() {
    set_invuln(65535);
    set_hurtbox(16fx);
    set_hitbox(12fx);
    move_vel(0, 90deg, 3fx, EASE_LINEAR);
    move_vel(60, 90deg, 0fx, EASE_QUAD_IN);
    spawn shots();
    wait(400);
    move_speed(120, 2fx, EASE_QUAD_IN);
    loop { wait(600); }
}

async sub wave() {
    wait(120);
    _ = spawn_enemy(64fx, -48fx, 1200, 0, 1000, 17, girl);
    _ = spawn_enemy(0fx, -48fx, 1200, 0, 1000, 16, girl);
    _ = spawn_enemy(-64fx, -48fx, 1200, 0, 1000, 17, girl);
    loop { wait(600); }
}

async sub encounter() {
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_invuln(65535);
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(600); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, encounter);
    loop { wait(600); }
}
